      if (dateTh && dateTh.textContent.trim()) {
        currentDate = dateTh.textContent.trim();
      }

      const matchTd = tr.querySelector('td.match');
      const infoTd = tr.querySelector('td.info');
      const commentTd = tr.querySelector('td.comment');

