    ...pDate
  });
}

// Region assignments
const regions = {
  "エスコンＦ": 1,
  "楽天モバイル": 2,
  "ベルーナドーム": 3,
  "東京ドーム": 3,
  "神宮": 3,
  "ZOZOマリン": 3,
  "横浜": 3,
  "バンテリンドーム": 4,
  "京セラD大阪": 5,
  "甲子園": 5,
  "マツダスタジアム": 6,
  "みずほPayPay": 7
};

// Let's test both forward order (Region 1 -> 2 -> 3 -> 4 -> 5 -> 6 -> 7) 
// and reverse order (Region 7 -> 6 -> 5 -> 4 -> 3 -> 2 -> 1).
// Also allow small variations if needed.

function findItineraries(regionOrder) {
  const results = [];

  // For each stadium, group available games
  const byStadium = {};
  for (const s of STADIUMS) {
    byStadium[s] = cleanGames.filter(g => g.place === s).sort((a, b) => a.dayNum - b.dayNum);
  }

  // Let's generate potential sequences of stadiums adhering to regionOrder
  // Region 3 has 5 stadiums (any permutation), Region 5 has 2 stadiums (any permutation)
  // To avoid huge search space, let's do a backtracking search:
  // state: current stadium index in itinerary (0..11), chosen games: []

  // stadium sequence templates:
  const kantoStadiums = ["ベルーナドーム", "東京ドーム", "神宮", "ZOZOマリン", "横浜"];
  const kansaiStadiums = ["京セラD大阪", "甲子園"];

  // Let's check how many total games we can chain.
  // Actually, let's write a generic dynamic programming or DFS with pruning:
  // stadium_visited bitmask (12 bits), last_dayNum, last_region

  function dfs(visitedMask, lastGame, path) {
    if (path.length === 12) {
      const span = path[11].dayNum - path[0].dayNum + 1;
      results.push({ span, path: [...path] });
      return;
    }

    // Choose next stadium
    for (let i = 0; i < 12; i++) {
      if ((visitedMask & (1 << i)) === 0) {
        const nextStadium = STADIUMS[i];
        const nextRegion = regions[nextStadium];

        // Region constraint: must not go backwards in region order
        if (regionOrder === 'north_to_south') {
          if (lastGame && nextRegion < regions[lastGame.place]) continue;
        } else if (regionOrder === 'south_to_north') {
          if (lastGame && nextRegion > regions[lastGame.place]) continue;
        }

        // Find games for this stadium strictly after lastGame.dayNum
        const candidateGames = byStadium[nextStadium].filter(g => {
          if (!lastGame) return true;
          const diff = g.dayNum - lastGame.dayNum;
          return diff >= 1 && diff <= 3; // at most 2 rest/travel days between games
        });

        for (const g of candidateGames) {
          dfs(visitedMask | (1 << i), g, [...path, g]);
          if (results.length >= 100) return; // limit to 100
        }
      }
    }
  }

  dfs(0, null, []);
  return results;
}

