async function searchBooking(query) {
  const url = `https://www.booking.com/searchresults.html?ss=${encodeURIComponent(query)}`;
  await tool.navigate({ tabId, url });
  await tool.wait_for({ tabId, condition: "load_state", value: "domcontentloaded", timeout_ms: 15000 });
  await new Promise(r => setTimeout(r, 2000));

  return await browserjs(tabId, () => {
    const cards = Array.from(document.querySelectorAll('[data-testid="property-card"]'));
    return cards.slice(0, 3).map(c => ({
      title: c.querySelector('[data-testid="title"]')?.textContent?.trim(),
      score: c.querySelector('[data-testid="review-score"]')?.textContent?.trim()?.replace(/\s+/g, ' '),
      distance: c.querySelector('[data-testid="distance"]')?.textContent?.trim(),
      link: c.querySelector('a[data-testid="title-link"]')?.href
    }));
  });
}

